START TRANSACTION;


DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261104194006_Phase5') THEN
    CREATE TABLE "Ai_ImportDrafts" (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY,
        "Kind" character varying(10) NOT NULL,
        "FileName" character varying(200) NOT NULL,
        "Json" text NOT NULL,
        "Status" character varying(10) NOT NULL,
        "Result" character varying(500),
        "CreatedOn" timestamp with time zone NOT NULL,
        "CreatedBy" character varying(256) NOT NULL,
        "AppliedOn" timestamp with time zone,
        CONSTRAINT "PK_Ai_ImportDrafts" PRIMARY KEY ("Id")
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261104194006_Phase5') THEN
    CREATE TABLE "Alert_Rules" (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY,
        "Name" character varying(120) NOT NULL,
        "Metric" character varying(40) NOT NULL,
        "Comparator" character varying(10) NOT NULL,
        "Threshold" numeric(18,2) NOT NULL,
        "WindowMinutes" integer NOT NULL,
        "FromHour" integer NOT NULL,
        "ToHour" integer NOT NULL,
        "Channels" character varying(80) NOT NULL,
        "Recipients" character varying(500),
        "CooldownMinutes" integer NOT NULL,
        "IsActive" boolean NOT NULL,
        "LastFiredOn" timestamp with time zone,
        "CreatedOn" timestamp with time zone NOT NULL,
        CONSTRAINT "PK_Alert_Rules" PRIMARY KEY ("Id")
    );
    END IF;
END $EF$;

DO $EF$
